template:
fn char_info(s: &str, index: usize) -> (usize, Option<char>) {
    let count = s.⟦count_op⟧;
    let ch = s.⟦char_op⟧;
    (count, ch)
}

fn main() {
    let (len, c) = char_info("🦀 Rust", 0);
    println!("{len}, {c:?}");
}

tests:
#[test]
fn test_char_info() {
    let (count, ch) = char_info("🦀 Rust", 0);
    assert_eq!(count, 6);
    assert_eq!(ch, Some('🦀'));
    let (count2, ch2) = char_info("hello", 1);
    assert_eq!(count2, 5);
    assert_eq!(ch2, Some('e'));
}
